package com.smartparking.database;
import java.sql.*;import java.io.*;import java.util.*;
public final class DBConnection { private DBConnection(){} public static Connection open() throws SQLException {Properties p=new Properties();String configured=System.getenv("PARKING_DB_CONFIG");File file=configured==null?(new File("application.properties").isFile()?new File("application.properties"):new File("src/main/resources/application.properties")):new File(configured);try(InputStream in=new FileInputStream(file)){p.load(in);}catch(IOException e){throw new SQLException("Cannot read database configuration file: "+file.getPath(),e);}String url=System.getenv().getOrDefault("PARKING_DB_URL",p.getProperty("db.url"));if(url==null||url.isBlank())throw new SQLException("db.url is missing from the database configuration");String user=System.getenv().getOrDefault("PARKING_DB_USER",p.getProperty("db.user",""));String password=System.getenv().getOrDefault("PARKING_DB_PASSWORD",p.getProperty("db.password",""));return DriverManager.getConnection(url,user,password);} }
